bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}' 2>/dev/null)" = true || exit 60
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import {readFileSync,existsSync} from 'node:fs';
import {createHash} from 'node:crypto';
for(const p of ['src/telegram/paidListingPublisher.mjs','src/telegram/freeAlbum.mjs','src/telegram/paidMedia.mjs','src/runtime/creatorPollingMain.mjs','owner/gateOwner.mjs']){
 const full='/opt/videobot/'+p;
 if(!existsSync(full)){console.log(p+' MISSING');continue}
 const b=readFileSync(full);
 const h=createHash('sha1').update(Buffer.from('blob '+b.length+'\0')).update(b).digest('hex');
 const s=b.toString();
 console.log(p+' blob='+h+' sendPaidMedia='+s.includes('sendPaidMedia')+' paid_media='+s.includes('paid_media')+' stars='+s.includes('star_count')+' gate='+s.includes('getVerifiedVideoTopic'));
}
JS
